"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { CheckCircle, AlertCircle, Loader2, Plus, Trash2, Upload } from "lucide-react";
import Layout from "../../Layout";

export default function CreateSortie() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split("T")[0],
    bon: null,
    type: "Bon de sortie",
    products: [{ productId: "", quantity: "" }],
    chefName: "", // Stores the selected chef's _id
  });
  const [products, setProducts] = useState([]);
  const [chefs, setChefs] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    fetchProducts();
    fetchChefs();
  }, []);

  const fetchProducts = async () => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("Vous devez être connecté pour récupérer les produits.");
      return;
    }
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/products`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setProducts(response.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des produits");
    }
  };

  const fetchChefs = async () => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("Vous devez être connecté pour récupérer les chefs.");
      return;
    }
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/chefs`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setChefs(response.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des chefs");
    }
  };

  const handleChange = (e, index) => {
    const { name, value, files } = e.target;
    if (index === undefined) {
      if (name === "bon" && files?.length > 0) {
        const file = files[0];
        if (file.size > 5 * 1024 * 1024) {
          setError("L'image doit être inférieure à 5 Mo.");
          return;
        }
        if (!file.type.startsWith("image/")) {
          setError("Seules les images sont autorisées.");
          return;
        }
        setFormData({ ...formData, bon: file });
        const reader = new FileReader();
        reader.onloadend = () => setPreviewImage(reader.result);
        reader.readAsDataURL(file);
      } else {
        setFormData({ ...formData, [name]: value });
      }
    } else {
      const updatedProducts = [...formData.products];
      updatedProducts[index][name] = value;
      setFormData({ ...formData, products: updatedProducts });
    }
  };

  const addProduct = () => {
    setFormData({
      ...formData,
      products: [...formData.products, { productId: "", quantity: "" }],
    });
  };

  const removeProduct = (index) => {
    if (formData.products.length === 1) return;
    const updatedProducts = formData.products.filter((_, i) => i !== index);
    setFormData({ ...formData, products: updatedProducts });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");
    if (!token) {
      setError("Vous devez être connecté pour créer une sortie.");
      setIsSubmitting(false);
      return;
    }

    if (!formData.chefName) {
      setError("Veuillez sélectionner un chef.");
      setIsSubmitting(false);
      return;
    }
    for (const product of formData.products) {
      if (!product.productId || !product.quantity || parseInt(product.quantity) <= 0) {
        setError("Tous les produits doivent avoir un ID et une quantité valide (> 0).");
        setIsSubmitting(false);
        return;
      }
    }

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("date", formData.date);
      formDataToSend.append("type", formData.type);
      formDataToSend.append("chefName", formData.chefName); // Sending chef's _id
      if (formData.bon) {
        formDataToSend.append("bon", formData.bon);
      }

      const productsToSend = formData.products.map((product) => ({
        productId: product.productId,
        quantity: parseInt(product.quantity),
      }));
      formDataToSend.append("products", JSON.stringify(productsToSend));

      await axios.post(`${process.env.REACT_APP_API_URL}/api/sorties`, formDataToSend, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });

      setSuccess("Sortie créée avec succès !");
      setTimeout(() => navigate("/ManageSortie"), 2000);
    } catch (err) {
      console.error("Erreur Frontend complète:", err);
      const errorMessage = err.response?.data?.message || "Erreur lors de la création de la sortie";
      setError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Créer une Sortie</h2>
            <p className="text-white/80 mt-1 text-sm">Enregistrer une sortie de stock</p>
          </div>

          {(error || success) && (
            <div
              className={`m-6 p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } rounded-r-lg flex items-center gap-3`}
            >
              {error ? <AlertCircle className="h-5 w-5 text-red-500" /> : <CheckCircle className="h-5 w-5 text-green-500" />}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6">
            <div className="space-y-8">
              <div className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50">
                <h3 className="text-lg font-medium text-[#00717F] mb-4">Informations de la Sortie</h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
                    <input
                      type="date"
                      name="date"
                      value={formData.date}
                      onChange={handleChange}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-[#00717F] focus:border-[#00717F]"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Nom du Chef</label>
                    <select
                      name="chefName"
                      value={formData.chefName}
                      onChange={handleChange}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-[#00717F] focus:border-[#00717F]"
                      required
                    >
                      <option value="">Sélectionner un chef</option>
                      {chefs.map((chef) => (
                        <option key={chef._id} value={`${chef.firstName} ${chef.lastName}`}>
                          {`${chef.firstName} ${chef.lastName}`}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Image du Bon (max 5 Mo)</label>
                    <input
                      type="file"
                      name="bon"
                      accept="image/*"
                      onChange={handleChange}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg text-gray-700 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#00717F] file:text-white hover:file:bg-[#C8A45D]"
                    />
                    {previewImage && (
                      <div className="mt-2">
                        <img src={previewImage} alt="Aperçu" className="h-20 object-contain rounded-md" />
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {formData.products.map((product, index) => (
                <div key={index} className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50 relative">
                  <button
                    type="button"
                    onClick={() => removeProduct(index)}
                    className="absolute top-4 right-4 text-red-600 hover:text-red-800 disabled:opacity-50"
                    disabled={formData.products.length === 1}
                  >
                    <Trash2 className="h-5 w-5" />
                  </button>
                  <h3 className="text-lg font-medium text-[#00717F] mb-4">Produit {index + 1}</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Produit</label>
                      <select
                        name="productId"
                        value={product.productId}
                        onChange={(e) => handleChange(e, index)}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-[#00717F] focus:border-[#00717F]"
                        required
                      >
                        <option value="">Sélectionner un produit</option>
                        {products.map((p) => (
                          <option key={p._id} value={p._id}>
                            {p.nameProduct} ({p.quantity} {p.unity === "unit" ? "unité" : p.unity})
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Quantité</label>
                      <input
                        type="number"
                        name="quantity"
                        value={product.quantity}
                        onChange={(e) => handleChange(e, index)}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-[#00717F] focus:border-[#00717F]"
                        min="1"
                        required
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <div className="mt-6 flex justify-between">
              <button
                type="button"
                onClick={addProduct}
                className="px-5 py-2.5 bg-[#00717F] text-white rounded-lg hover:bg-[#C8A45D] flex items-center gap-2 font-medium transition-colors"
              >
                <Plus className="h-4 w-4" /> Ajouter un Produit
              </button>
              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={() => navigate("/ManageSortie")}
                  className="px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium transition-colors"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="px-5 py-2.5 bg-[#00717F] text-white rounded-lg hover:opacity-90 font-medium flex items-center gap-2 disabled:opacity-50 transition-opacity"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" /> Traitement...
                    </>
                  ) : (
                    "Créer la Sortie"
                  )}
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </Layout>
  );
}
